sql.20261231030000_ranni_souhrn_sudy_stk_a_t:
-- 🔔 Ranní souhrn umí víc + středeční upozornění na mlčící odběratele.
--
-- Návrhy z 13. 9. 2026 (páté kolo), body 12 a 13:
--
--  • Ranní souhrn dosud hlásil jen čekající WhatsApp zprávy a výčepy po
--    termínu. Přibývá:
--      – končící nebo prošlá STK a dálniční známka (stejný práh 30 dní jako
--        lib/vozidla.ts — do teď to viděl jen ten, kdo otevřel Domů),
--      – sudy dlouho u odběratele (stejné pravidlo jako lib/sudyVenku.ts:
--        nevrácené sudy a od posledního vrácení, případně prvního odvozu,
--        uplynulo aspoň 30 dní).
--    „Docházející zboží" se do souhrnu záměrně NEPŘIDÁVÁ: stav skladu počítá
--    skladová kniha v aplikaci (lib/stockLedger.ts) z dvanácti tabulek a
--    druhá kopie téhož výpočtu v SQL by se od ní dřív nebo později rozešla.
--
--  • Pravidelný odběratel, který mlčí déle, než je u něj obvyklé. Seznam
--    existuje v kontrole objednávek (lib/kontrolaObjednavek.ts,
--    tichoUOdberatelu), ale vidí ho jen ten, kdo tu kontrolu otevře. Push jde
--    ve středu ráno — ještě je čas zavolat před čtvrtečním a pátečním
--    závozem. Pravidlo je stejné: aspoň 4 zprávy za poslední 3 měsíce,
--    ticho delší než 2,5× medián odstupů a zároveň aspoň 7 dní.

CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;

CREATE OR REPLACE FUNCTION public.posli_ranni_souhrn()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_secret text;
  v_whatsapp_cekajici int;
  v_vycepy_po_terminu int;
  v_kauce_czk numeric;
  v_vozidla int;
  v_vozidla_nazvy text;
  v_sudy_mist int;
  v_sudy_kusu int;
  v_radky text[] := ARRAY[]::text[];
  v_stranka text;
BEGIN
  SELECT value INTO v_secret FROM app_secrets WHERE key = 'WHATSAPP_CRON_SECRET';
  IF v_secret IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*) INTO v_whatsapp_cekajici
  FROM whatsapp_incoming
  WHERE status IN ('pending', 'parsed', 'error');

  SELECT count(*), coalesce(sum(kauce_czk), 0)
  INTO v_vycepy_po_terminu, v_kauce_czk
  FROM vycepy_rezervace
  WHERE vraceno = false
    AND coalesce(datum_do, datum_od) <= current_date - interval '2 days';

  SELECT count(*), string_agg(coalesce(nullif(spz, ''), name), ', ' ORDER BY name)
  INTO v_vozidla, v_vozidla_nazvy
  FROM vehicles
  WHERE (stk_valid_until IS NOT NULL AND stk_valid_until <= current_date + 30)
     OR (highway_toll_valid_until IS NOT NULL AND highway_toll_valid_until <= current_date + 30);

  WITH konto AS (
    SELECT
      coalesce(place_id::text, 'name:' || lower(coalesce(place_name, ''))) AS klic,
      sum(CASE WHEN direction = 'out' THEN quantity ELSE -quantity END) AS pocet,
      max(entry_date) FILTER (WHERE direction = 'in') AS posledni_vraceni,
      min(entry_date) FILTER (WHERE direction = 'out') AS prvni_odvoz
    FROM keg_returns
    GROUP BY 1
  )
  SELECT count(*), coalesce(sum(pocet), 0)
  INTO v_sudy_mist, v_sudy_kusu
  FROM konto
  WHERE klic <> 'name:'
    AND pocet > 0
    AND current_date - coalesce(posledni_vraceni, prvni_odvoz) >= 30;

  IF v_whatsapp_cekajici = 0 AND v_vycepy_po_terminu = 0 AND v_vozidla = 0 AND v_sudy_mist = 0 THEN
    RETURN;
  END IF;

  IF v_whatsapp_cekajici > 0 THEN
    v_radky := v_radky || (v_whatsapp_cekajici::text || 'x WhatsApp objednávka čeká na schválení');
    v_stranka := coalesce(v_stranka, 'orders');
  END IF;
  IF v_vycepy_po_terminu > 0 THEN
    v_radky := v_radky || (v_vycepy_po_terminu::text || 'x výčep po termínu (kauce ' || v_kauce_czk::text || ' Kč)');
    v_stranka := coalesce(v_stranka, 'vycepy');
  END IF;
  IF v_sudy_mist > 0 THEN
    v_radky := v_radky || (v_sudy_kusu::text || ' sudů leží přes 30 dní u ' || v_sudy_mist::text || ' odběratelů');
    v_stranka := coalesce(v_stranka, 'zavoz');
  END IF;
  IF v_vozidla > 0 THEN
    v_radky := v_radky || ('STK nebo dálniční známka končí: ' || v_vozidla_nazvy);
    v_stranka := coalesce(v_stranka, 'catalogs');
  END IF;

  PERFORM net.http_post(
    url := 'https://sasqexjadvlqyticxwja.supabase.co/functions/v1/posli-push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Internal-Cron-Secret', v_secret
    ),
    body := jsonb_build_object(
      'titulek', 'Ranní souhrn',
      'telo', array_to_string(v_radky, ' · '),
      'stranka', v_stranka,
      'tag', 'ranni-souhrn'
    )
  );
END;
$$;

COMMENT ON FUNCTION public.posli_ranni_souhrn() IS
  'Denní push: WhatsApp čeká na schválení, výčepy po termínu, sudy přes 30 dní u odběratele, končící STK/známka. Viz docs/20-navrhu-2026-09-13.md body 12-13.';

CREATE OR REPLACE FUNCTION public.posli_tydenni_ticho()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_secret text;
  v_pocet int;
  v_jmena text;
BEGIN
  SELECT value INTO v_secret FROM app_secrets WHERE key = 'WHATSAPP_CRON_SECRET';
  IF v_secret IS NULL THEN
    RETURN;
  END IF;

  WITH zpravy AS (
    SELECT trim(sender_name) AS kdo, created_at
    FROM whatsapp_incoming
    WHERE coalesce(trim(sender_name), '') <> ''
      AND created_at >= now() - interval '3 months'
  ),
  odstupy AS (
    SELECT kdo, created_at,
      extract(epoch FROM created_at - lag(created_at) OVER (PARTITION BY kdo ORDER BY created_at)) / 86400 AS odstup
    FROM zpravy
  ),
  rytmus AS (
    SELECT kdo,
      count(*) AS pocet,
      percentile_cont(0.5) WITHIN GROUP (ORDER BY odstup) FILTER (WHERE odstup IS NOT NULL) AS obvykle,
      max(created_at) AS posledni
    FROM odstupy
    GROUP BY kdo
  ),
  mlci AS (
    SELECT kdo, extract(epoch FROM now() - posledni) / 86400 / obvykle AS pomer
    FROM rytmus
    WHERE pocet >= 4
      AND obvykle > 0
      AND extract(epoch FROM now() - posledni) / 86400 >= greatest(7, obvykle * 2.5)
  )
  SELECT count(*), string_agg(kdo, ', ' ORDER BY pomer DESC)
  INTO v_pocet, v_jmena
  FROM mlci;

  IF v_pocet = 0 THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := 'https://sasqexjadvlqyticxwja.supabase.co/functions/v1/posli-push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Internal-Cron-Secret', v_secret
    ),
    body := jsonb_build_object(
      'titulek', 'Odběratelé se neozvali',
      'telo', v_pocet::text || ' pravidelných odběratelů mlčí déle než obvykle: ' || v_jmena,
      'stranka', 'orders',
      'tag', 'tydenni-ticho'
    )
  );
END;
$$;

COMMENT ON FUNCTION public.posli_tydenni_ticho() IS
  'Středeční push: pravidelní odběratelé, kteří mlčí déle než 2,5× obvyklý odstup (stejně jako lib/kontrolaObjednavek.ts tichoUOdberatelu).';

-- Středa 5:00 UTC = 7:00 v létě, 6:00 v zimě (stejný kompromis jako ranní souhrn).
SELECT cron.schedule(
  'tydenni-ticho-push',
  '0 5 * * 3',
  $$SELECT public.posli_tydenni_ticho();$$
);

-- Volat smí jen plánovač (běží jako vlastník), ne přihlášený uživatel.
REVOKE ALL ON FUNCTION public.posli_ranni_souhrn() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.posli_tydenni_ticho() FROM PUBLIC, anon, authenticated;

sql.20261231040000_historie_zmen_cen.sql:
-- 💰 Historie změn cen.
--
-- Návrh z 13. 9. 2026 (páté kolo), bod 20. Ceník (obrazovka Ceník) přepisuje
-- cenu na místě: cena za litr sudového piva je sloupec beers.price_per_liter
-- a cena lahve se v price_list aktualizuje UPDATEm. Po změně tak nikde
-- nezůstalo, kolik to stálo předtím a kdy se zdražilo — přesně to, na co se
-- odběratel ptá.
--
-- Zápis dělají triggery, ne obrazovka: cenu jde změnit i jinudy (import,
-- ruční zásah v Supabase) a historie, která zná jen jednu cestu, by lhala.

CREATE TABLE IF NOT EXISTS public.cenik_zmeny (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  druh text NOT NULL CHECK (druh IN ('litr', 'kus')),
  beer_id uuid REFERENCES public.beers(id) ON DELETE SET NULL,
  package_id uuid REFERENCES public.packages(id) ON DELETE SET NULL,
  stara_cena numeric,
  nova_cena numeric,
  zmenil uuid DEFAULT auth.uid()
);

CREATE INDEX IF NOT EXISTS cenik_zmeny_created_idx ON public.cenik_zmeny (created_at DESC);

ALTER TABLE public.cenik_zmeny ENABLE ROW LEVEL SECURITY;

-- Číst smí každý přihlášený (ceník vidí všichni). Zapisují jen triggery níž
-- (SECURITY DEFINER) — ruční INSERT/UPDATE/DELETE z aplikace nejde, aby se
-- historie nedala přepsat.
DROP POLICY IF EXISTS cenik_zmeny_select ON public.cenik_zmeny;
CREATE POLICY cenik_zmeny_select ON public.cenik_zmeny
  FOR SELECT TO authenticated USING (true);

CREATE OR REPLACE FUNCTION public.zapis_zmenu_ceny_piva()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.price_per_liter IS DISTINCT FROM OLD.price_per_liter THEN
    INSERT INTO public.cenik_zmeny (druh, beer_id, stara_cena, nova_cena)
    VALUES ('litr', NEW.id, OLD.price_per_liter, NEW.price_per_liter);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS beers_zmena_ceny ON public.beers;
CREATE TRIGGER beers_zmena_ceny
  AFTER UPDATE OF price_per_liter ON public.beers
  FOR EACH ROW EXECUTE FUNCTION public.zapis_zmenu_ceny_piva();

CREATE OR REPLACE FUNCTION public.zapis_zmenu_ceny_lahve()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.cenik_zmeny (druh, beer_id, package_id, stara_cena, nova_cena)
    VALUES ('kus', NEW.beer_id, NEW.package_id, NULL, NEW.price_per_unit);
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.price_per_unit IS DISTINCT FROM OLD.price_per_unit THEN
      INSERT INTO public.cenik_zmeny (druh, beer_id, package_id, stara_cena, nova_cena)
      VALUES ('kus', NEW.beer_id, NEW.package_id, OLD.price_per_unit, NEW.price_per_unit);
    END IF;
    RETURN NEW;
  ELSE
    INSERT INTO public.cenik_zmeny (druh, beer_id, package_id, stara_cena, nova_cena)
    VALUES ('kus', OLD.beer_id, OLD.package_id, OLD.price_per_unit, NULL);
    RETURN OLD;
  END IF;
END;
$$;

DROP TRIGGER IF EXISTS price_list_zmena_ceny ON public.price_list;
CREATE TRIGGER price_list_zmena_ceny
  AFTER INSERT OR UPDATE OF price_per_unit OR DELETE ON public.price_list
  FOR EACH ROW EXECUTE FUNCTION public.zapis_zmenu_ceny_lahve();

REVOKE ALL ON FUNCTION public.zapis_zmenu_ceny_piva() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.zapis_zmenu_ceny_lahve() FROM PUBLIC, anon, authenticated;

-- Realtime, ať se nový záznam v historii ukáže bez obnovení stránky.
DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.cenik_zmeny;
EXCEPTION WHEN duplicate_object OR undefined_object THEN NULL;
END $$;

sql.20261231050000_varky_mereni_a_kvasnice.s:
-- 🧪 Várky ve sklepě: průběh kvašení a generace kvasnic.
--
-- Návrhy z 13. 9. 2026 (páté kolo), body 9 a 11. Tabulka cellar_batches
-- existuje od srpna 2026, ale žádná obrazovka do ní nepsala (komentář
-- u tabulky to přiznává: „legacy — doposud žádný kód nepíše"). Várka měla
-- jen počáteční a konečnou stupňovitost, takže průběh kvašení se nikde
-- nezapisoval, a generaci kvasnic appka neznala vůbec.

ALTER TABLE public.cellar_batches
  ADD COLUMN IF NOT EXISTS kvasnice_generace integer,
  ADD COLUMN IF NOT EXISTS kvasnice_z_varky uuid REFERENCES public.cellar_batches(id) ON DELETE SET NULL;

ALTER TABLE public.cellar_batches DROP CONSTRAINT IF EXISTS cellar_batches_generace_kladna;
ALTER TABLE public.cellar_batches
  ADD CONSTRAINT cellar_batches_generace_kladna CHECK (kvasnice_generace IS NULL OR kvasnice_generace >= 1);

COMMENT ON TABLE public.cellar_batches IS
  'Várky v tancích sklepa. Zapisuje obrazovka Sklep → Várky (components/VarkySklep.tsx).';
COMMENT ON COLUMN public.cellar_batches.kvasnice_generace IS
  'Kolikátá generace kvasnic (1 = čerstvé). Při nasazení z jiné várky appka navrhne generaci o jedna vyšší.';

CREATE TABLE IF NOT EXISTS public.cellar_batch_mereni (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  batch_id uuid NOT NULL REFERENCES public.cellar_batches(id) ON DELETE CASCADE,
  measured_at timestamptz NOT NULL DEFAULT now(),
  stupnovitost numeric,
  teplota_c numeric,
  poznamka text,
  zapsal text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT cellar_batch_mereni_neco_namereno CHECK (stupnovitost IS NOT NULL OR teplota_c IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS cellar_batch_mereni_batch_idx ON public.cellar_batch_mereni (batch_id, measured_at);

ALTER TABLE public.cellar_batch_mereni ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS cellar_batch_mereni_select ON public.cellar_batch_mereni;
CREATE POLICY cellar_batch_mereni_select ON public.cellar_batch_mereni
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS perm_insert_cellar_batch_mereni ON public.cellar_batch_mereni;
CREATE POLICY perm_insert_cellar_batch_mereni ON public.cellar_batch_mereni
  FOR INSERT TO authenticated WITH CHECK (public.user_can_edit_module('cellar'));

DROP POLICY IF EXISTS perm_update_cellar_batch_mereni ON public.cellar_batch_mereni;
CREATE POLICY perm_update_cellar_batch_mereni ON public.cellar_batch_mereni
  FOR UPDATE TO authenticated
  USING (public.user_can_edit_module('cellar'))
  WITH CHECK (public.user_can_edit_module('cellar'));

DROP POLICY IF EXISTS perm_delete_cellar_batch_mereni ON public.cellar_batch_mereni;
CREATE POLICY perm_delete_cellar_batch_mereni ON public.cellar_batch_mereni
  FOR DELETE TO authenticated USING (public.user_can_edit_module('cellar'));

DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.cellar_batches;
EXCEPTION WHEN duplicate_object OR undefined_object THEN NULL;
END $$;

DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.cellar_batch_mereni;
EXCEPTION WHEN duplicate_object OR undefined_object THEN NULL;
END $$;

sql.20261231100000_mista_duplicity_ignorovan:
/*
# Ignorované páry podezřelých duplicit odběratelů

Audit 16.–17. 9. 2026 upozornil na několik odběratelů se skoro stejným
jménem/adresou (Malenovice/Malenovoce, Zizkov/Ma Zizkov...) — ale automatické
sloučení je nebezpečné (16. 9. 2026 navržený merge "petr" + "Petr moravcik
prodejna" by spojil DVA různé reálné lidi). Appka proto jen NABÍZÍ podezřelé
páry k ruční kontrole (viz PlacesScreen) a obsluha sama řekne "sloučit" nebo
"nechat" — tahle tabulka pamatuje páry označené jako "nejsou duplicita", ať
appka příště neotravuje se stejným párem znovu.
*/

CREATE TABLE IF NOT EXISTS public.mista_duplicity_ignorovano (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  place_id_a uuid NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
  place_id_b uuid NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text
);

ALTER TABLE public.mista_duplicity_ignorovano ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "mista_duplicity_ignorovano_select" ON public.mista_duplicity_ignorovano;
CREATE POLICY "mista_duplicity_ignorovano_select" ON public.mista_duplicity_ignorovano
  FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "mista_duplicity_ignorovano_insert" ON public.mista_duplicity_ignorovano;
CREATE POLICY "mista_duplicity_ignorovano_insert" ON public.mista_duplicity_ignorovano
  FOR INSERT TO authenticated WITH CHECK (true);
DROP POLICY IF EXISTS "mista_duplicity_ignorovano_delete" ON public.mista_duplicity_ignorovano;
CREATE POLICY "mista_duplicity_ignorovano_delete" ON public.mista_duplicity_ignorovano
  FOR DELETE TO authenticated USING (true);

CREATE INDEX IF NOT EXISTS idx_mista_duplicity_ignorovano_a ON public.mista_duplicity_ignorovano(place_id_a);
CREATE INDEX IF NOT EXISTS idx_mista_duplicity_ignorovano_b ON public.mista_duplicity_ignorovano(place_id_b);
